/**
 * The picture of each music genre on the Genres tab, drawn from the path data of the 64x64 SVG files (one colour, the
 * card tints it). A bad path can only produce a blank icon, never a crash. Which genre name gets which picture is
 * decided by [GenreKind.of].
 */
object GenreIcons {
    fun of(kind: GenreKind): ImageVector = when (kind) {
        GenreKind.Rock -> Rock
        GenreKind.AlternativeRock -> AlternativeRock
        GenreKind.Pop -> Pop
        GenreKind.HipHop -> HipHop
        GenreKind.Trap -> Trap
        GenreKind.Rap -> Rap
        GenreKind.Laika -> Laika
        GenreKind.Entechno -> Entechno
        GenreKind.Electronic -> Electronic
        GenreKind.FunkDisco -> FunkDisco
        GenreKind.Jazz -> Jazz
        GenreKind.RnbSoul -> RnbSoul
        GenreKind.Metal -> Metal
        GenreKind.Classical -> Classical
    }

