    private class P(val data: String, val evenOdd: Boolean)

    private fun build(name: String, vararg paths: P): ImageVector {
        val builder = ImageVector.Builder(
            name = name,
            defaultWidth = 64.dp,
            defaultHeight = 64.dp,
            viewportWidth = 64f,
            viewportHeight = 64f,
        )
        for (p in paths) {
            try {
                builder.addPath(
                    pathData = PathParser().parsePathString(p.data).toNodes(),
                    pathFillType = if (p.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                    fill = SolidColor(Color.Black),
                )
            } catch (e: Exception) {
                // Blank part instead of a crash.
            }
        }
        return builder.build()
    }
